/** Swap the person with the one above (`up`) or below (`down`) them in the list; refused (rejects)
 *  for the first moving up or the last moving down. */
export function movePerson(sheetId: string, by: string, id: number, direction: 'up' | 'down'): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/move?by=${encodeURIComponent(by)}`, { direction });
}

/** Add a hold on the person from `from` (blank: the sheet's today) to `to` (blank: open-ended);
 *  refused (rejects) when a date is not a date or `to` is before `from`. */
export function holdPerson(sheetId: string, by: string, id: number, from: string, to: string): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/hold?by=${encodeURIComponent(by)}`, { from, to });
}

/** Name another person on the sheet as one of the person's patrons; refused (rejects) for the
 *  person themselves or a patron already named. */
export function addPatron(sheetId: string, by: string, id: number, patronId: number): Promise<Person> {
  return postJson<Person>(`${base(sheetId)}/${id}/patrons?by=${encodeURIComponent(by)}`, { patronId });

export type Person = {
  id: number; sheetId: string; name: string; grade: Grade; grades: GradeFrom[]; version: number;
  statementCount: number; statedTotal: string | null; statementDate: string | null;
  retired: boolean; retiredFrom: string | null; retiredReached: boolean;
  /** Their past retirements, oldest first: a claim dated after one's from and before its to is refused. */
  retirements: Retirement[];
  /** The SNAPSHOTs written for them, oldest first: the day being left and their due-total on it (or n/a). */
  snapshots: Snapshot[];
  /** Their statements still standing (a cancelled one is gone), oldest first: by date, then as taken. */
  statements: StatementLine[];
  held: boolean; holds: Hold[]; patronIds: number[];
  /** Their own terms in whole days in force on the sheet's today (null: none): a claim's due-by goes by
   *  those in force on its date before their grade's or the sheet's. */
  terms: number | null;
  /** Their own terms from the beginning of time (null: none). */
    mutationFn: (id: number) => unretirePerson(sheetId, user, id),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    ]),
  });

  // The person whose last hold was refused; cleared by the next action on the row.
  const holding = useMutation({
    mutationFn: (v: { id: number; from: string; to: string }) => holdPerson(sheetId, user, v.id, v.from, v.to),
    onSuccess: () => Promise.all([
      queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: claimsKey(sheetId) }),
      queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) }),
    ]),
  });

  // The person whose last patron added was refused; cleared by the next action on the row.
  const patronage = useMutation({
    mutationFn: (v: { id: number; patronId: number }) => addPatron(sheetId, user, v.id, v.patronId),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: peopleKey(sheetId) }),
  });

  // The person whose last alias added was refused; cleared by the next action on the row.
  const aliasing = useMutation({
  const watching = useMutation({
    mutationFn: (v: { id: number; on: boolean }) => watchPerson(sheetId, user, v.id, v.on),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: watchesKey(sheetId, user) }),
  });

  const resetRowActions = () => {
    statement.reset();
    unstatement.reset();
    watching.reset();
    retirement.reset();
    unretirement.reset();
    holding.reset();
    patronage.reset();
    aliasing.reset();
    merging.reset();
    transferring.reset();
    untransferring.reset();
    moving.reset();
    grading.reset();
  };

  const grade = (p: Person) => {
    const picked = gradePicks[p.id] ?? p.grade;
    stateOnce(() => {
      resetRowActions();
      return grading.mutateAsync({ id: p.id, person: p, grade: picked });
    });
  };

  const move = (id: number, direction: 'up' | 'down') => {
    stateOnce(() => {
  const unretire = (id: number) => {
    stateOnce(() => {
      resetRowActions();
      return unretirement.mutateAsync(id);
    });
  };

  const hold = (id: number) => {
    const { from = '', to = '' } = holdDates[id] ?? {};
    stateOnce(() => {
      resetRowActions();
      return holding.mutateAsync({ id, from, to });
    });
  };

  const changeHold = (id: number, patch: Partial<{ from: string; to: string }>) => {
    setHoldDates((d) => ({ ...d, [id]: { from: '', to: '', ...d[id], ...patch } }));
    holding.reset();
  };

  const patronize = (id: number) => {
    const patronId = Number(patronPicks[id] ?? '');
    stateOnce(() => {
      resetRowActions();
      return patronage.mutateAsync({ id, patronId });
    });
